        var freemem = os.freemem() / 1048576;
        var status = {
          uid: process.getuid(),
          pid: process.pid,
          versions: process.versions,
          memory: process.memoryUsage(),
          uptime: (process.uptime() / 1000) + 's'
        };
        client.write(JSON.stringify(status));
        break;


      default:
        client.write('Unknown signal');

    }

  });

});
