var startApp = function (program, client) {

  // if the sock file already exists, free it by deleting it - probably caused by a crash
  if (fs.existsSync(paths.appSock)) fs.unlinkSync(paths.appSock);

  if (program.enableApi) {
    // necessary setups
    // it is the user's responsibility to make sure the module is loaded!
  }

  var out = fs.openSync(paths.appStdOut, 'a');
  var err = fs.openSync(paths.appStdErr, 'a');

  var spawnOptions = [];
  if (program.harmony) spawnOptions.push('--harmony');
  spawnOptions.push(appInfo.mainFilePath);

  var app = spawn('node', spawnOptions, {
    cwd: process.cwd(),
    env: process.env,
    stdio: [ 'ignore', out, err ]
  });

  app.on('exit', function () {

    if (appmanUtils.appIsRestarting()) {

      if (srClient) {
        var message = 'restartInit' + appmanUtils.DELIM0 + JSON.stringify({
          event: 'restartInit',
          time: Date.now(),
          pid: app.pid
        });
        srClient.write(message);
      }

      appmanUtils.log(appNameVersion + ' restarting ...');

      var startOptions = appmanUtils.getStartOptions(appmanUtils.getAppPid());
      var argv = startOptions.split(appmanUtils.DELIM1);

      if (fs.existsSync(paths.appSock)) fs.unlinkSync(paths.appSock);
      appmanUtils.deregisterApp(app.pid);
      // if (fs.existsSync(paths.appPid)) fs.unlinkSync(paths.appPid); we are not deleting this to indicate a crash
      appmanUtils.log(appNameVersion + ' with PID ' + app.pid + ' terminated');
      startApp(argv);

    }
    else {

      if (srClient) {
        var message = 'stop' + appmanUtils.DELIM0 + JSON.stringify({
          event: 'stop',
          time: Date.now(),
          pid: app.pid
        });
        srClient.write(message);
      }

    }

  });

  appStartTime = Date.now();

  // record the app pid
  fs.writeFileSync(paths.appPid, app.pid);

  appInfo.pid = app.pid;
  var res = { error: false, appNameVersion: appNameVersion, pid: app.pid };
  if (client) client.write(JSON.stringify(res));

  if (appmanUtils.appIsRestarting()) {
    restartCount++;
    appmanUtils.unsetRestarting();
    appmanUtils.log(appNameVersion + ' restarted with PID ' + app.pid);
    appRestartedOn = Date.now();

    if (srClient) {
      var message = 'restart' + appmanUtils.DELIM0 + JSON.stringify({
        event: 'restart',
        time: appRestartedOn,
        pid: app.pid
      });
      srClient.write(message);
    }

  }
  else {
    appmanUtils.log(appNameVersion + ' started with PID ' + app.pid);
    appStartedOn = Date.now();

    if (srClient) {
      var message = 'start' + appmanUtils.DELIM0 + JSON.stringify({
        event: 'start',
        time: appStartedOn,
        pid: app.pid
      });
      srClient.write(message);
    }

  }

  appmanUtils.registerApp(appNameVersion, app.pid, process.cwd(), appInfo.mainFileName, Math.floor(Date.now()/1000), argv.join(appmanUtils.DELIM1));

  // start the app in the background
  app.unref();

  if (program.revive) { reviveApp(program); }

  if (program.watch) {

    if (!watchingFiles) {

      var watchPatterns = [];
      if (program.watchFiles) { program.watchFiles.split(',').forEach(function (pattern) { watchPatterns.push(pattern.trim()); }); }
      else watchPatterns = '*.js'; // by default, will watch js files in the current dir

      gaze(watchPatterns, function(error, watcher) {

        if (error) throw error;

        var validInterval = 1000;
        var lastEventTime;

        this.on('all', function(event, filepath) {

          lastEventTime = Date.now();

          // prevent event flood
          (function (thisEventTime) {

            setTimeout(function () {
              if (thisEventTime == lastEventTime) {

                // don't worry about specifying restart logs here - the process exit and app start events will know if it is a restart or not
                appmanUtils.setRestarting();
                process.kill(appmanUtils.getAppPid(), 'SIGINT');

              }
            }, validInterval);

          })(lastEventTime);

        });

      });

      watchingFiles = true;

    }

  }

}

