module.exports = function (appNameVersion, appInfo) {

  return function (program) {

    var appWasAlive = false;

    var reset = function () {

      if (appWasAlive) console.log('\n ✓'.bold + ' %s terminated', appNameVersion);
      else console.log('\n ✓'.bold + ' %s not running', appNameVersion);

      if (appmanUtils.monitorIsAlive()) {
        var monitorPid = fs.readFileSync(paths.monitorPid).toString();
        process.kill(monitorPid, 'SIGINT');
        console.log(' ✓'.bold + ' Monitor terminated');
        fs.unlinkSync(paths.monitorPid);
        console.log(' ✓'.bold + ' Monitor PID file deleted');
      }
      else console.log(' ✓'.bold + ' Monitor not running');

      if (fs.existsSync(paths.restartingFlag)) {
        fs.unlinkSync(paths.restartingFlag);
        console.log(' ✓'.bold + ' Restart file deleted');
      }
      else { console.log(' ✓'.bold + ' No failed restarts'); }

      rmdir(paths.appmanDir, function (error) { return error && console.log(error); });
      console.log(' ✓'.bold + ' Local .appman directory deleted');

      if (fs.existsSync(paths.appmanMasterRecordFile)) fs.unlinkSync(paths.appmanMasterRecordFile);
      console.log(' ✓'.bold + ' Global .appman file deleted');

      if (fs.existsSync(paths.appmanSock)) fs.unlinkSync(paths.appmanSock);
      console.log(' ✓'.bold + ' Terminal sock file deleted');

      if (appmanUtils.scriptRunnerIsAlive()) {
        appmanUtils.stopScriptRunner();
        console.log(' ✓'.bold + ' Script runner terminated');
        if (fs.existsSync(paths.scriptRunnerPid)) fs.unlinkSync(paths.scriptRunnerPid);
        console.log(' ✓'.bold + ' Script runner PID file deleted');
        if (fs.existsSync(paths.scriptRunnerSock)) fs.unlinkSync(paths.scriptRunnerSock);
        console.log(' ✓'.bold + ' Script runner sock file deleted');
      }

      appmanUtils.terminateRunawayProcesses(function () {
        console.log('\n Appman is reset\n'.cyan);
        if (program.audible) appmanUtils.say('Appman is reset');
        process.exit();
      });

    }

    if (appmanUtils.appIsAlive()) {

      appWasAlive = true;

      fs.readFile(paths.appPid, function (error, data) {

        if (error) return console.log('\n %s is not running\n', appNameVersion.bold);

        var pid = data.toString();
        fs.unlinkSync(paths.appPid);

        process.kill(pid, 'SIGINT'); // kill the process 'respectfully'
        // the sock file will be created only if the appman module was loaded in the app
        if (fs.existsSync(paths.appSock)) fs.unlinkSync(paths.appSock);

        appmanUtils.log(appNameVersion + ' with PID ' + pid + ' stopped');
        //console.log('\n %s with PID %s stopped\n', appNameVersion.bold, pid.toString().bold);
        reset();

      });

    }
    else { reset(); }


  }

}

